import json
g=[[0]*12 for _ in range(11)]
ys={1:{6},2:{5,6,7},3:{7},4:{6,7,8},5:{6,7}}
for r,c in ys.items():
    for col in c: g[r][col]=4
flip={10-r0:cols for r0,cols in ys.items()}  # rows1-5 -> 6-10? 1->? 
# explicit: row1->row10? No: mirror directly below means row5->6,4->7,3->8,2->9,1->10
flip={6:ys[5],7:ys[4],8:ys[3],9:ys[2],10:ys[1]}
for r,c in flip.items():
    for col in c: g[r][col]=4
for row in g: print(row)
print(json.dumps({"action":"submit","grid":g}))

