import json
g=[[0]*12 for _ in range(11)]
ys={1:{6},2:{5,6,7},3:{7},4:{6,7,8},5:{6,7}}
for r,c in ys.items():
    for col in c: g[r][col]=4
# left-right mirror of the shape (bbox cols5-8, axis 6.5: c->13-c)
mir={r:{13-c for c in cols} for r,cols in ys.items()}
# appended below rows6-10, same row order (LR flip doesn't reverse row order)
for i,r in enumerate(sorted(ys)):
    for col in mir[r]: g[6+i][col]=4
for row in g: print(row)
print(json.dumps({"action":"submit","grid":g}))

